globalThis.__MATH1_LESSON_BANK__=MATH1_LESSON_BANK;

function clean(v){return String(v||'').replace(/\s+/g,' ').trim()}
function normalize(v){return clean(v).toLowerCase().replace(/[−–—]/g,'-').replace(/[≤]/g,'<=').replace(/[≥]/g,'>=').replace(/\s+/g,'')}
function isMasteryStep(st,idx,guide){return !!st?.questions||/mastery|quick check/i.test(clean(st?.t))||idx===guide.steps.length-1}
function standardText(ch,idx){
  let s=(ch.sections||[])[Math.min(idx,Math.max(0,(ch.sections||[]).length-1))];
  let std=s?.math?.standard||{};
  return clean(std.shortDescription||std.description||std.id||'');
}
function chapterSpecs(ch){return MATH1_LESSON_BANK[Number(ch.number)]||MATH1_LESSON_BANK[1]}
function specFor(ch,guide,idx,st){
  let bank=chapterSpecs(ch),mastery=isMasteryStep(st,idx,guide);
  if(mastery){
    let fallback=bank[Math.min(bank.length-1,idx%bank.length)];
    return {...fallback,kind:'mastery',focus:'Chapter mastery',core:`Mix the chapter skills instead of repeating one procedure. Decide what structure the problem has, choose an efficient method, solve, and verify.`,try:st?.try&&!GENERIC_MATH.test(st.try)?st.try:fallback.try,answer:st?.tryAnswer||fallback.answer,apply:'State the method you chose and the independent check you used.'};
  }
  return bank[idx%bank.length];
}
function deepenMathGuide(ch,guide){
  if(S.subject!=='math'||!guide||!Array.isArray(guide.steps))return guide;
  let steps=guide.steps.map((st,idx)=>{
    let sp=specFor(ch,guide,idx,st),mastery=isMasteryStep(st,idx,guide);
    if(mastery&&st.questions)return {...st,math1:sp,learn:sp.core,more:sp.why};
    return {...st,
      math1:sp,
      t: clean(st.t)||sp.focus,
      learn:sp.core,
      see:sp.steps,
      try:sp.try,
      tryAnswer:sp.answer,
      apply:sp.apply,
      more:sp.why,
      v:sp.kind==='graph'?'cards':'cards',
      choices:undefined,
      sort:undefined,
      sequence:undefined
    };
  });
  return {...guide,big:`${clean(guide.big)} Every block now teaches a different mathematical action: learn the idea, study one worked example, solve a new problem, then verify or interpret it.`.trim(),steps,math1Deep:true};
}
guideFor=function(ch){return deepenMathGuide(ch,previousGuideFor(ch))};

function stateKey(ch,idx){return `math-${ch.number}-lesson-v4-${idx}`}
function lessonState(ch,idx){let x=saved[stateKey(ch,idx)]||{};return x&&typeof x==='object'?x:{}}
function saveLessonState(ch,idx,patch){
  saved[stateKey(ch,idx)]={...lessonState(ch,idx),...patch,updatedAt:new Date().toISOString()};
  saved[`${S.subject}-${ch.number}-progress`]=Math.max(Number(saved[`${S.subject}-${ch.number}-progress`]||0),.15);
  save();
}
function renderMath(v){return formatMathNotation(esc(v))}
function taskLabel(kind){return ({discovery:'Find the structure',solve:'Solve',error:'Error detective',classification:'Classify',formula:'Rewrite the formula',model:'Model the situation',translate:'Translate and graph','sign-rule':'Sign rule',compound:'Compound inequality',absolute:'Distance reasoning',function:'Function test',evaluate:'Evaluate',rate:'Rate of change',equation:'Build the equation',compare:'Compare representations',graph:'Graph / represent',form:'Equivalent forms',parallel:'Parallel / perpendicular',sequence:'Sequence rule',table:'Data to equation',substitution:'Substitution',elimination:'Elimination',inequality:'Solution region',exponent:'Exponent structure',growth:'Growth model',decay:'Decay model',geometric:'Geometric sequence',center:'Center',spread:'Spread',sampling:'Sampling',inference:'Inference',scatter:'Association',uncertainty:'Uncertainty',coordinate:'Coordinate geometry',distance:'Distance',angle:'Angle relationship',perimeter:'Geometry model','coordinate-line':'Coordinate lines',reasoning:'Choose the tool',conditional:'Logic',counterexample:'Counterexample',inductive:'Conjecture',deductive:'Deduction',proof:'Proof',diagram:'Diagram evidence',transversal:'Transversal angles','parallel-slope':'Parallel slopes','perpendicular-slope':'Perpendicular slopes',converse:'Converse theorem',mixed:'Mixed reasoning',translation:'Translation',reflection:'Reflection',rotation:'Rotation',dilation:'Dilation',composition:'Composition',properties:'Invariants','angle-sum':'Angle sum',exterior:'Exterior angle',sas:'Congruence',asa:'Congruence',hl:'Right-triangle congruence',similarity:'Similarity',mastery:'Mixed mastery'}[kind]||'Practice')}
function visualFor(kind){
  if(['graph','coordinate','coordinate-line','translation','reflection','rotation','dilation','composition'].includes(kind)&&typeof blankCoordinateGridHtml==='function')return blankCoordinateGridHtml();
  if(['translate','sign-rule','compound','absolute'].includes(kind)&&typeof blankNumberLineHtml==='function')return blankNumberLineHtml();
  return '';
}
function math1ResponseControl(ch,idx,st,sp){
  if(st.questions){
    return `<div class="check-grid">${st.questions.map((q,i)=>`<label><strong>${i+1}. ${renderMath(q)}</strong><textarea data-autosave-key="${esc(guideSaveKey(idx,'q'+i))}" placeholder="Solve or explain here.">${esc(saved[guideSaveKey(idx,'q'+i)]||'')}</textarea></label>`).join('')}</div>`;
  }
  let state=lessonState(ch,idx),key=guideSaveKey(idx,'try'),value=saved[key]||'';
  return `<div class="guided-math-try math1-varied-task" data-kind="${esc(sp.kind)}">
    <div class="eyebrow">${esc(taskLabel(sp.kind))}</div>
    <p class="math-question">${renderMath(sp.try)}</p>
    ${visualFor(sp.kind)}
    <textarea data-autosave-key="${esc(key)}" placeholder="${sp.kind==='error'?'Identify the error, correct it, and give the final result.':sp.kind==='graph'?'Record key points/features and your conclusion.':'Show the essential work and final answer.'}">${esc(value)}</textarea>
    <button class="secondary no-print" onclick="checkMath1LessonTry(${idx})">Check my attempt</button>
    <div class="guided-try-feedback">${state.reviewed?`<div class="feedback"><strong>Comparison answer:</strong> ${renderMath(sp.answer)}<br><span>${esc(sp.apply)}</span></div>`:''}</div>
  </div>`;
}
globalThis.checkMath1LessonTry=function(idx){
  let ch=chap(),guide=guideFor(ch),st=guide.steps[idx],sp=st.math1||specFor(ch,guide,idx,st),key=guideSaveKey(idx,'try'),value=clean(saved[key]||'');
  if(!value){alert('Make an honest attempt before checking the comparison answer.');return}
  saveLessonState(ch,idx,{attempted:true,reviewed:true,attempt:value,comparison:sp.answer});
  render(false);
}
globalThis.completeMath1LessonBlock=function(idx){
  let ch=chap(),guide=guideFor(ch),st=guide.steps[idx];
  if(st.questions){
    if(st.questions.some((_,i)=>!clean(saved[guideSaveKey(idx,'q'+i)]||''))){alert('Answer every mastery question before completing this block.');return}
  }else if(!lessonState(ch,idx).reviewed){
    alert('Solve the Try It problem and check your attempt before completing this block.');return
  }
  saved[`math-${ch.number}-guide-done-${idx}`]=true;
  saved[`math-${ch.number}-guide-completedAt-${idx}`]=new Date().toISOString();
  saved[`math-${ch.number}-progress`]=Math.max(Number(saved[`math-${ch.number}-progress`]||0),(idx+1)/guide.steps.length);
  if(idx<guide.steps.length-1)saved[`math-${ch.number}-guide-step`]=idx+1;
  save();navigate();window.scrollTo(0,0);
}
mathGuidedLesson=function(ch,guide){
  if(S.subject!=='math')return previousMathGuidedLesson(ch,guide);
  let key=`math-${ch.number}-guide-step`,idx=Math.max(0,Math.min(guide.steps.length-1,Number(saved[key]||0))),st=guide.steps[idx],sp=st.math1||specFor(ch,guide,idx,st);
  let done=guide.steps.filter((_,i)=>saved[`math-${ch.number}-guide-done-${i}`]).length,pct=Math.round(done/guide.steps.length*100),mastery=!!st.questions;
  let ready=mastery?st.questions.every((_,i)=>clean(saved[guideSaveKey(idx,'q'+i)]||'')):!!lessonState(ch,idx).reviewed;
  let std=standardText(ch,idx);
  return `<div class="card math-path">
    <div class="eyebrow">Integrated Math I · Chapter ${ch.number} · Block ${idx+1} of ${guide.steps.length}</div>
    <h1>${injectTerms(st.t,ch)}</h1>
    <p>${renderMath(sp.focus)}</p>
    <div class="progress"><span style="width:${pct}%"></span></div>
    <p class="muted">${done} of ${guide.steps.length} blocks complete. Each block uses a different task, not a repeated mental-drill template.</p>
    <div class="guide-pills">${guide.steps.map((s,i)=>`<button class="${i===idx?'current':''} ${saved[`math-${ch.number}-guide-done-${i}`]?'done':''}" onclick="setGuideStep(${i})">${i+1}</button>`).join('')}</div>
  </div>
  <div class="card guide-card math3-guide math1-deep-guide">
    <div class="math-rule-grid">
      <article><small>LEARNING TARGET</small><strong>${renderMath(sp.focus)}</strong></article>
      <article><small>CORE IDEA</small><strong>${renderMath(sp.core)}</strong></article>
      <article><small>${std?'STANDARD FOCUS':'CHECK HABIT'}</small><strong>${std?esc(std):'Use a second method, substitution, units, graph feature, or reasonableness check.'}</strong></article>
    </div>
    ${mastery?'':`<h3>Worked example</h3><div class="worked-solution"><p class="worked-answer">${renderMath(sp.worked)}</p><ol>${sp.steps.map(x=>`<li>${renderMath(x)}</li>`).join('')}</ol><p><strong>Result:</strong> ${renderMath(sp.workedAnswer)}</p><p class="muted">${renderMath(sp.why)}</p></div>`}
    <div class="interaction guide-try"><h3>${mastery?'Chapter mastery':'Try It — new problem'}</h3>${math1ResponseControl(ch,idx,st,sp)}</div>
    <div class="actions no-print">
      <button class="secondary" ${idx===0?'disabled':''} onclick="setGuideStep(${idx-1})">Previous block</button>
      <button class="primary" ${ready?'':'disabled'} onclick="completeMath1LessonBlock(${idx})">${idx===guide.steps.length-1?'Complete math chapter path':'Complete block and continue'}</button>
      <button class="secondary" ${idx===guide.steps.length-1?'disabled':''} onclick="setGuideStep(${idx+1})">Next block</button>
      ${ready?'':'<span class="muted complete-hint">Make an attempt and review the comparison answer to continue.</span>'}
    </div>
  </div>`;
};

function auditBank(){
  let report=[];
  for(let ch=1;ch<=12;ch++){
    let rows=MATH1_LESSON_BANK[ch]||[],prompts=rows.map(x=>normalize(x.try)),unique=new Set(prompts),kinds=new Set(rows.map(x=>x.kind));
    report.push({chapter:ch,lessons:rows.length,uniquePrompts:unique.size,kinds:kinds.size,duplicatePrompts:rows.length-unique.size});
  }
  return report;
}
globalThis.__auditMath1Lessons=auditBank;
try{if(S.view==='chapter'&&S.subject==='math'&&typeof render==='function')render(false)}catch(_){}
